{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "Unencrypted root EBS volume",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "HIGH",
      "explanation": "The launch configuration does not explicitly encrypt its root EBS volume, which may expose data at rest if the selected AMI does not enforce encryption."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "IMDSv1 is not disabled",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "HIGH",
      "explanation": "The launch configuration does not require IMDSv2, leaving instances susceptible to credential theft through attacks that can access the instance metadata service."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"levelup-launchconfig\" {\n  name_prefix   = \"levelup-launchconfig\"\n  image_id      = lookup(var.AMIS, var.AWS_REGION)\n  instance_type = \"t2.micro\"\n  key_name      = aws_key_pair.levelup_key.key_name\n\n  root_block_device {\n    encrypted = true\n  }\n\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n}\n",
  "fix_summary": "Enabled encryption for the root EBS volume and required IMDSv2 for instances created from the launch configuration."
}
